-- 20848689 | ما هي فروض الكفاية المتعلقة بالميت المسلم؟
UPDATE qa_questions SET
  answer = 'هي عند البهوتي في كشاف القناع: غُسله، وتكفينه، والصلاة عليه، ودفنه متوجِّهًا إلى القبلة، وحملُه — ولفظه: «غسل الميت المسلم وتكفينه والصلاة عليه ودفنه متوجهًا إلى القبلة وحمله فرض كفاية»؛ وكذا مُؤْنة الحمل والدفن إن لم يخلِّف شيئًا ولم يكن له وارث ولم يمكن الأخذ من بيت المال، كباقي مُؤَن التجهيز. وإنما تجب على من علم به من المسلمين، لأن من لم يعلم به معذور؛ فإذا قام بها من يكفي سقط الإثم عن الباقين، وصلاةُ الجنازة يُسقط فرضَها واحد رجلًا كان أو امرأة أو خنثى.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٢/ص٨٥ و١٠٩ و١٢٦ (فصل في غسل الميت وما يتعلق به، وفصل في الصلاة على الميت، وفصل حمل المسلم ودفنه من فروض الكفاية) | الكلمات المفتاحية: فروض الكفاية، الجنائز',
  evidence = 'كشاف القناع ج٢/ص٨٥: «غُسْلُ الْمَيِّتِ الْمُسْلِمِ وَتَكْفِينُهُ وَالصَّلَاةُ عَلَيْهِ وَدَفْنُهُ مُتَوَجِّهًا إلَى الْقِبْلَةِ وَحَمْلُهُ فَرْضُ كِفَايَةٍ»، لقوله ﷺ في الذي وقصته راحلته: «اغْسِلُوهُ بِمَاءٍ وَسِدْرٍ وَكَفِّنُوهُ فِي ثَوْبَيْهِ» متفق عليه، وقوله ﷺ: «صَلُّوا عَلَى مَنْ قَالَ لَا إلَهَ إلَّا اللَّهُ». وج٢/ص١٢٦: «(فَصْلٌ حَمْلُهُ وَدَفْنُهُ مِنْ فُرُوضِ الْكِفَايَةِ) وَتَقَدَّمَ (وَكَذَا مُؤْنَتُهُمَا) أَيْ: مُؤْنَةُ الْحَمْلِ وَالدَّفْنِ فَهِيَ فَرْضُ كِفَايَةٍ، إنْ لَمْ يَخْلُفْ شَيْئًا وَلَمْ يَكُنْ لَهُ وَارِثٌ وَلَمْ يُمْكِنْ الْأَخْذُ مِنْ بَيْتِ الْمَالِ وَالْمُرَادُ عَلَى مَنْ عَلِمَ بِهِ مِنْ الْمُسْلِمِينَ كَبَاقِي مُؤَنِ التَّجْهِيزِ». وفي الصلاة عليه ج٢/ص١٠٩: «وَإِنَّمَا تَجِبُ عَلَى مَنْ عَلِمَ بِالْمَيِّتِ مِنْ الْمُسْلِمِينَ لِأَنَّ مَنْ لَمْ يَعْلَمْ بِهِ مَعْذُورٌ»، و«يُسْقِطُ فَرْضَهَا وَاحِدٌ رَجُلًا كَانَ أَوْ امْرَأَةً أَوْ خُنْثَى». (الأقواس في الكشاف تحصر متنَ الإقناع، وما بينها من غير قوسين شرحُ البهوتي.)',
  verification_status = 'verified'
WHERE id = '20848689-723b-4441-8ca8-8c0036e8dee8'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: فروض الكفاية، الجنائز'
  AND evidence = 'مسألة فقهية مجمَع عليها بين المذاهب، مبسوطة في كتب الفقه.'
  AND answer = 'غسله وتكفينه والصلاة عليه ودفنه، فإذا قام بها من يكفي سقط الإثم عن باقي المسلمين.';

-- 567cf9a6 | ما حكم صلاة الجنازة؟
UPDATE qa_questions SET
  answer = 'صلاةُ الجنازة فرضُ كفاية على المسلمين تجاه الميت المسلم، لأمر الشارع بها في غير حديث والأمر للوجوب — لكن البهوتي في كشاف القناع يقيِّدها بقوله: «وهي فرض كفاية على غير شهيد معركة ومقتول ظلمًا». وإنما تجب على من علم بالميت من المسلمين، لأن من لم يعلم به معذور، ويُسقط فرضَها واحدٌ رجلًا كان أو امرأة أو خنثى. وهي أربع تكبيرات، وليس فيها ركوع ولا سجود؛ والواجب من صفتها ستة أشياء: القيام إن كانت فرضًا، والتكبيرات الأربع، وقراءة الفاتحة على الإمام والمنفرد، والصلاة على النبي ﷺ، والدعاء للميت، والتسليمة.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٢/ص١٠٩ و١١٦ و١١٧ (فصل في الصلاة على الميت) | الكلمات المفتاحية: صلاة الجنازة',
  evidence = 'كشاف القناع ج٢/ص١٠٩: «وَهِيَ فَرْضُ كِفَايَةٍ عَلَى غَيْرِ شَهِيدِ مَعْرَكَةٍ وَمَقْتُولٍ ظُلْمًا لِأَمْرِ الشَّارِعِ بِهَا فِي غَيْرِ حَدِيثٍ كَقَوْلِهِ: - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «صَلُّوا عَلَى أَطْفَالِكُمْ فَإِنَّهُمْ أَفْرَاطُكُمْ»… وَقَوْلِهِ: «صَلُّوا عَلَى مَنْ قَالَ: لَا إلَهَ إلَّا اللَّهُ» وَالْأَمْرُ لِلْوُجُوبِ وَإِنَّمَا تَجِبُ عَلَى مَنْ عَلِمَ بِالْمَيِّتِ مِنْ الْمُسْلِمِينَ لِأَنَّ مَنْ لَمْ يَعْلَمْ بِهِ مَعْذُورٌ»، ثم: «يُسْقِطُ فَرْضَهَا وَاحِدٌ رَجُلًا كَانَ أَوْ امْرَأَةً أَوْ خُنْثَى». وفي واجباتها ج٢/ص١١٦: «(وَالْوَاجِبُ مِنْ ذَلِكَ) الْمَذْكُورِ فِي صِفَةِ الصَّلَاةِ عَلَى الْجِنَازَةِ سِتَّةُ أَشْيَاءَ أَحَدُهَا: (الْقِيَامُ إنْ كَانَتْ الصَّلَاةُ فَرْضًا)… (وَ) الثَّانِي (التَّكْبِيرَاتُ الْأَرْبَعُ)» لما روى ابن عباس وأبو هريرة وجابر «أَنَّهُ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - كَبَّرَ أَرْبَعًا» متفق عليه، وفيها: «دَلِيلُ إجْمَاعِهِمْ عَلَى أَنَّهُ لَا بُدَّ مِنْ أَرْبَعِ تَكْبِيرَاتٍ». وج٢/ص١١٧: «(الْفَاتِحَةِ عَلَى إمَامٍ وَمُنْفَرِدٍ)… (وَ) الرَّابِعُ (الصَّلَاةُ عَلَى النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -)… (وَ) الْخَامِسُ (دَعْوَةٌ) لِلْمَيِّتِ»، و«السَّادِسُ (تَسْلِيمَةٌ)».',
  verification_status = 'verified'
WHERE id = '567cf9a6-78ac-4c58-ac84-750094be87eb'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: صلاة الجنازة'
  AND evidence = 'مسألة فقهية مجمَع عليها بين الفقهاء.'
  AND answer = 'صلاة الجنازة فرض كفاية على المسلمين تجاه الميت المسلم، فإذا قام بها من يكفي سقط الإثم عن الباقين، وهي أربع تكبيرات بلا ركوع ولا سجود.';

-- a113f9f8 | ما شروط صحة الصلاة؟
UPDATE qa_questions SET
  answer = 'شروطُ الصلاة عند البهوتي في كشاف القناع تسعةٌ: الإسلامُ، والعقلُ، والتمييزُ — وهذه الثلاثة شرطٌ في كل عبادة، ولذلك أسقطها صاحب المقنع وغيره — والطهارةُ من الحدث الأكبر والأصغر، ودخولُ الوقت، وسترُ العورة، واجتنابُ النجاسة أي طهارة بدن المصلي وثيابه وموضع صلاته من نجاسة غير معفوٍّ عنها، واستقبالُ القبلة، والنيةُ وبها تمّت الشروط. والشرطُ ما تتوقف عليه صحة مشروطه ويستمر حكمه إلى انقضاء الصلاة، فمتى أخلّ بشرط لغير عذر لم تنعقد صلاته ولو كان ناسيًا له أو جاهلًا به.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج١/ص٢٤٨ و٢٤٩ و٢٦٣ و٢٨٨ و٣٠٢ و٣١٣ (باب شروط الصلاة وما بعده من أبوابها) | الكلمات المفتاحية: شروط الصلاة',
  evidence = 'كشاف القناع ج١/ص٢٤٨: «(وَهِيَ) أَيْ: شُرُوطُ الصَّلَاةِ (تِسْعَةٌ: الْإِسْلَامُ، وَالْعَقْلُ، وَالتَّمْيِيزُ) وَهَذِهِ الثَّلَاثَةُ شَرْطٌ فِي كُلِّ عِبَادَةٍ وَلِذَلِكَ أَسْقَطَهَا فِي الْمُقْنِعِ وَغَيْرِهِ»، ثم «الرَّابِعُ (الطَّهَارَةُ مِنْ الْحَدَثِ) الْأَكْبَرِ وَالْأَصْغَرِ» لقوله ﷺ: «لَا يَقْبَلُ اللَّهُ صَلَاةً بِغَيْرِ طُهُورٍ» رواه مسلم. وج١/ص٢٤٩: «(وَالْخَامِسُ دُخُولُ الْوَقْتِ)» لقوله تعالى ﴿أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ﴾. وج١/ص٢٦٣: «(وَهُوَ) أَيْ: سَتْرُ الْعَوْرَةِ. (الشَّرْطُ السَّادِسُ)». وج١/ص٢٨٨: «(الشَّرْطُ السَّابِعُ) لِلصَّلَاةِ لِتَقَدُّمِ سِتَّةٍ قَبْلَهُ (طَهَارَةُ بَدَنِ الْمُصَلِّي وَ) طَهَارَةُ (ثِيَابِهِ وَ) طَهَارَةُ (مَوْضِعِ صَلَاتِهِ… مِنْ نَجَاسَةٍ غَيْرِ مَعْفُوٍّ عَنْهَا) وَعَدَمِ حَمْلِهَا (شَرْطٌ لِصِحَّةِ الصَّلَاةِ)». وج١/ص٣٠٢ في الاستقبال: «(وَهُوَ الشَّرْطُ الثَّامِنُ لِصِحَّةِ الصَّلَاةِ) لِأَنَّهُ قَدْ تَقَدَّمَ عَلَيْهِ سَبْعَةٌ (فَلَا تَصِحُّ) الصَّلَاةُ (بِدُونِهِ)». وج١/ص٣١٣ في النية: «(وَهِيَ الشَّرْطُ التَّاسِعُ) وَبِهَا تَمَّتْ شُرُوطُ الصَّلَاةِ». وحكمُ الإخلال بها ج١/ص٢٤٨: «(فَمَتَى أَخَلَّ بِشَرْطٍ لِغَيْرِ عُذْرٍ لَمْ تَنْعَقِدْ صَلَاتُهُ) لِفَقْدِ شَرْطِهَا (وَلَوْ) كَانَ التَّارِكُ لِلشَّرْطِ (نَاسِيًا) لَهُ (أَوْ جَاهِلًا) بِهِ».',
  verification_status = 'verified'
WHERE id = 'a113f9f8-b6dc-4319-a0b3-221745dd439d'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: شروط الصلاة'
  AND evidence = 'مسألة فقهية مجمَع عليها بين الفقهاء، مبسوطة في كتب الفقه.'
  AND answer = 'دخول الوقت، والطهارة من الحدث والخبث، وستر العورة، واستقبال القبلة، والنية — فإذا اختل شرط منها بطلت الصلاة.';

-- c0008bac | ما أركان الحج؟
UPDATE qa_questions SET
  answer = 'أركانُ الحج أربعةٌ عند البهوتي في كشاف القناع: الوقوفُ بعرفة، وطوافُ الزيارة وهو طواف الإفاضة — قال ابن عبد البر: هو من فرائض الحج لا خلاف في ذلك بين العلماء — والسعيُ بين الصفا والمروة، والإحرامُ وهو نيةُ النسك. فمن ترك ركنًا، أو ترك النية له فيما تُعتبر فيه كالطواف والسعي، لم يتمّ نسكه إلا به، فلا يُجبَر تركُه بدم. بخلاف الواجبات وهي سبعة — الإحرام من الميقات، والوقوف بعرفة إلى الليل، والمبيت بمزدلفة، والمبيت بمنى، والرمي مرتَّبًا، والحِلاق أو التقصير، وطواف الوداع — فمن ترك واجبًا ولو سهوًا فعليه دم، ومن ترك سنة فلا شيء عليه. وأركانُ العمرة ثلاثة: الإحرام والطواف والسعي.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٢/ص٥٢١ و٥٢٢ (فصل أركان الحج) | الكلمات المفتاحية: أركان الحج',
  evidence = 'كشاف القناع ج٢/ص٥٢١: «(فَصْلٌ أَرْكَانُ الْحَجِّ) أَرْبَعَةٌ (الْوُقُوفُ بِعَرَفَةَ) لِحَدِيثِ «الْحَجُّ عَرَفَةَ»… (وَطَوَافُ الزِّيَارَةِ) قَالَ ابْنُ عَبْدِ الْبَرِّ: هُوَ مِنْ فَرَائِضَ الْحَجِّ لَا خِلَافَ فِي ذَلِكَ بَيْنَ الْعُلَمَاءِ لِقَوْلِهِ تَعَالَى ﴿وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ﴾ (وَالسَّعْيُ) بَيْنَ الصَّفَا وَالْمَرْوَةِ… (وَالْإِحْرَامُ وَهُوَ النِّيَّةُ) أَيْ: نِيَّةُ النُّسُكِ» لحديث «إنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ». وفي واجباته: «(وَوَاجِبَاتُهُ) أَيْ: الْحَجِّ (سَبْعَةٌ: الْإِحْرَامُ مِنْ الْمِيقَاتِ)… (وَالْوُقُوفُ بِعَرَفَةَ إلَى اللَّيْلِ)… (وَالْمَبِيتُ بِمُزْدَلِفَةَ)… (وَالْمَبِيتُ بِمِنًى)… (وَالرَّمْيُ) لِلْجِمَارِ (مُرَتَّبًا)… (وَالْحِلَاقُ أَوْ التَّقْصِيرُ وَطَوَافُ الْوَدَاعِ)»، و«(وَأَرْكَانُ الْعُمْرَةِ) ثَلَاثَةٌ (الْإِحْرَامُ، وَالطَّوَافُ وَالسَّعْيُ)»، ثم الفرقُ بينهما: «(فَمَنْ تَرَكَ رُكْنًا، أَوْ) تَرَكَ (النِّيَّةَ لَهُ) إنْ اُعْتُبِرَتْ فِيهِ كَالطَّوَافِ وَالسَّعْيِ (لَمْ يَتِمَّ نُسُكُهُ إلَّا بِهِ)». وج٢/ص٥٢٢: «(وَمَنْ تَرَكَ وَاجِبًا) لِحَجٍّ أَوْ عُمْرَةٍ (وَلَوْ سَهْوًا فَعَلَيْهِ دَمٌ)»، و«(وَمَنْ تَرَكَ سُنَّةً فَلَا شَيْءَ عَلَيْهِ)».',
  verification_status = 'verified'
WHERE id = 'c0008bac-c54a-45cf-a6da-e2e190eda17a'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: أركان الحج'
  AND evidence = 'مسألة فقهية مجمع على أصلها مع خلاف يسير في تفاصيل بعضها بين المذاهب.'
  AND answer = 'أربعة أركان لا يصح الحج بدونها ولا يُجبَر تركها بدم: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي بين الصفا والمروة.';
